package main

import (
	"bufio"
	"fmt"
	"math"
	"os"
	"strconv"
)

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Split(bufio.ScanWords)

	n := nextInt(scanner)
	k := nextInt(scanner)

	minVal := math.MaxInt32

	for i := 1; i < k; i++ {
		if n%i == 0 {
			x := (n / i) * k + i
			if x < minVal {
				minVal = x
			}
		}
	}

	fmt.Print(minVal)
}

func nextInt(scanner *bufio.Scanner) int {
	scanner.Scan()
	val, _ := strconv.Atoi(scanner.Text())
	return val
}

